#!/bin/sh
# linq2db credentials CLI (protocol 1) over the HashiCorp Vault CLI: one KV secret per record, with the fields
# "username" and "password", at the record's target (linq2db/<name>) in the KV mount $LINQ2DB_VAULT_MOUNT (default:
# secret; KV version 1 or 2).
# Generated by "dotnet linq2db credentials cli init --store vault"; review it and edit it freely.
# The vault CLI finds the server and the token as usual: VAULT_ADDR, VAULT_TOKEN or the token helper (vault login).
# Secrets travel only on stdin/stdout. See CREDENTIALS-CLI.md, "linq2db credentials CLI protocol".
set -eu
umask 077
# sed is run with LC_ALL=C (byte semantics).

mount=${LINQ2DB_VAULT_MOUNT:-secret}

# Every answer starts with "protocol=1" and "status=<status>"; a run that ends without an answer (a failure) answers
# "status=error", with the reason on stderr.
answered=0
errors=''
answer() {
	answered=1
	printf 'protocol=1\nstatus=%s\n' "$1"
}
trap '[ -z "$errors" ] || rm -f "$errors"; [ "$answered" = 1 ] || printf "protocol=1\nstatus=error\n"' EXIT

fail() {
	printf '%s\n' "$1" >&2
	exit 1
}

protocol=''
verb=''
target=''
username=''
password=''
while IFS= read -r line || [ -n "$line" ]; do
	key=${line%%=*}
	value=${line#*=}
	case $key in
		protocol) protocol=$value ;;
		verb)     verb=$value ;;
		target)   target=$value ;;
		username) username=$value ;;
		password) password=$value ;;
		*) ;;
	esac
done

if [ "$protocol" != 1 ]; then
	answer unsupported
	exit 0
fi

errors=$(mktemp) || fail 'cannot create a temporary file'

# Runs vault with its standard error in $errors; its standard output (never ours: it carries the answer) is the
# caller's to capture. Its standard input is empty (the list loop reads its own) except for kv put, which reads the data.
v() {
	vault "$@" 2>"$errors" </dev/null
}

v_put() {
	vault kv put -mount="$mount" -- "$1" - 2>"$errors"
}

# Whether the last vault command failed because the path holds no secret ("No data found": KV version 2 keeps the
# metadata of a deleted or destroyed latest version).
missing() {
	LC_ALL=C grep -q '^No value found at \|^No data found at ' "$errors"
}

# Fails when a value holds a control character: the answer is line-based, and a line break in a user name stored by
# someone else would forge records.
check() {
	case $2 in
		*[[:cntrl:]]*) fail "$1 holds a control character" ;;
	esac
}

# Prints the strings of vault's JSON output (an array of keys), one per line, decoding the escapes encoding/json
# writes; fails on a string with a control character, which could not be one line.
json_strings() {
	LC_ALL=C awk '
		function hex(h,    i, c, v) {
			v = 0
			for (i = 1; i <= 4; i++) {
				c = index("0123456789abcdef", tolower(substr(h, i, 1)))
				if (c == 0)
					exit 2
				v = v * 16 + c - 1
			}
			return v
		}
		function utf8(v) {
			if (v < 128)
				return sprintf("%c", v)
			if (v < 2048)
				return sprintf("%c%c", 192 + int(v / 64), 128 + v % 64)
			return sprintf("%c%c%c", 224 + int(v / 4096), 128 + int(v / 64) % 64, 128 + v % 64)
		}
		{ text = text $0 "\n" }
		END {
			n = length(text)
			i = 1
			while (i <= n) {
				if (substr(text, i, 1) != "\"") {
					i++
					continue
				}
				value = ""
				i++
				while (1) {
					if (i > n)
						exit 2
					c = substr(text, i, 1)
					if (c == "\"") {
						i++
						break
					}
					if (c == "\\") {
						e = substr(text, i + 1, 1)
						if (e == "u") {
							v = hex(substr(text, i + 2, 4))
							if (v < 32 || v == 127 || (v >= 128 && v < 160) || (v >= 55296 && v < 57344))
								exit 3
							value = value utf8(v)
							i += 6
							continue
						}
						if (e != "\"" && e != "\\" && e != "/")
							exit 3
						value = value e
						i += 2
						continue
					}
					if (c < " " || c == "\177")
						exit 3
					value = value c
					i++
				}
				print value
			}
		}'
}

# Fails with vault's error on one line (the client shows only the first line of standard error).
vault_fail() {
	reason=$(LC_ALL=C tr '\n\t' '  ' < "$errors" | LC_ALL=C sed 's/URL: [A-Z]* [^ ]*//; s/  */ /g; s/^ //; s/ $//')
	fail "vault $1 failed: $reason"
}

# Reads one field of the secret at $1 into $field_value; returns 1 when the path holds no secret, 2 when the secret
# has no such field.
read_field() {
	if field_value=$(v kv get -mount="$mount" -field="$2" -- "$1"); then
		return 0
	fi
	if missing; then
		return 1
	fi
	if LC_ALL=C grep -q "^Field \"$2\" not present" "$errors"; then
		return 2
	fi
	vault_fail 'kv get'
}

# A JSON string: the protocol keeps line breaks out of values; backslashes and quotes are escaped.
json() {
	printf '"%s"' "$(printf '%s' "$1" | LC_ALL=C sed 's/\\/\\\\/g; s/"/\\"/g')"
}

# Prints "target=" and "username=" lines for every secret under the folder $1 (ending in /), depth first.
list_folder() {
	# JSON, not the table: the table trims and splits keys. An empty or missing folder prints {} and exits 2.
	if ! keys=$(v kv list -format=json -mount="$mount" -- "$1"); then
		if [ "$keys" = '{}' ] || missing; then
			return 0
		fi
		vault_fail 'kv list'
	fi
	entries=$(printf '%s\n' "$keys" | json_strings) || fail "vault kv list returned a key under $1 with a control character, or output that is not a JSON array of strings"
	printf '%s\n' "$entries" | while IFS= read -r entry; do
		[ -n "$entry" ] || continue
		case $entry in
			*/) list_folder "$1$entry" || exit 1 ;;
			*)
				user=''
				rc=0
				read_field "$1$entry" username || rc=$?
				# A deleted latest version (KV version 2) has no data but still a record to erase: listed without a user.
				case $rc in
					0) user=$field_value ;;
				esac
				check "the user name of $1$entry" "$user"
				printf '\ntarget=%s\nusername=%s\n' "$1$entry" "$user"
				;;
		esac
	done
}

case $verb in
	get)
		rc=0
		read_field "$target" password || rc=$?
		case $rc in
			1)
				answer not-found
				exit 0
				;;
			2) fail "the secret at $target in mount $mount has no password field" ;;
		esac
		secret=$field_value
		user=''
		rc=0
		read_field "$target" username || rc=$?
		case $rc in
			0) user=$field_value ;;
			1) fail "the secret at $target in mount $mount was removed while it was read" ;;
		esac
		check "the user name of $target" "$user"
		check "the password of $target" "$secret"
		answer ok
		printf 'username=%s\npassword=%s\n' "$user" "$secret"
		;;
	store)
		# The data goes to vault on stdin ("-"): never in the arguments, which other users can see.
		printf '{"username":%s,"password":%s}' "$(json "$username")" "$(json "$password")" \
			| v_put "$target" >/dev/null || vault_fail 'kv put'
		answer ok
		;;
	erase)
		# KV version 2: the record exists while its metadata does, readable data or not (a deleted latest version keeps
		# recoverable older ones); removing the metadata removes every version.
		if v kv metadata get -mount="$mount" -- "$target" >/dev/null; then
			v kv metadata delete -mount="$mount" -- "$target" >/dev/null || vault_fail 'kv metadata delete'
			answer ok
			exit 0
		fi
		if missing; then
			answer not-found
			exit 0
		fi
		LC_ALL=C grep -q 'Metadata not supported on KV Version 1' "$errors" || vault_fail 'kv metadata get'
		# KV version 1: one value, removed by a plain delete.
		rc=0
		read_field "$target" password || rc=$?
		if [ "$rc" = 1 ]; then
			answer not-found
			exit 0
		fi
		v kv delete -mount="$mount" -- "$target" >/dev/null || vault_fail 'kv delete'
		answer ok
		;;
	list)
		# Every record is read before the answer starts, so a failure is never reported after "status=ok".
		records=$(list_folder linq2db/) || exit 1
		answer ok
		if [ -n "$records" ]; then
			printf '%s\n' "$records"
		fi
		;;
	*)
		answer unsupported
		;;
esac
